-- Generated by `yidam export --format warehouse` from this corpus's ontology. Regenerate rather than edit; an edited file is refused on the next export.
--
-- The RFC-0049 warehouse contract, BigQuery dialect. Identifiers are unqualified: run
-- this with the target dataset as the job's default dataset, for example
--   bq query --use_legacy_sql=false --dataset_id=<project>:<dataset> < 0001_init.sql

CREATE TABLE IF NOT EXISTS `compute_instance` (
  `id` STRING NOT NULL OPTIONS(description="The row's identity within its origin: a node reference for `corpus`, the feed's `id:` expression otherwise."),
  `_origin` STRING NOT NULL OPTIONS(description="The feed that wrote the row: `corpus`, or a feed's name."),
  `_loaded_at` TIMESTAMP NOT NULL OPTIONS(description="When the feed SQL wrote the row."),
  `_source` STRING OPTIONS(description="The catalog slug the row's facts came from, when known."),
  `_corpus_commit` STRING OPTIONS(description="The commit a `corpus` row was exported from; null for every other origin."),
  `provider` STRING NOT NULL,
  `machine_type` STRING,
  `vcpus` FLOAT64,
  `created` DATE,
  `created_precision` STRING OPTIONS(description="How much of `created` was stated: `year`, `month` or `day`. `created` holds the first day of that interval."),
  PRIMARY KEY (`id`, `_origin`) NOT ENFORCED
) OPTIONS(description="A virtual machine in a cloud provider's inventory.");

CREATE TABLE IF NOT EXISTS `network` (
  `id` STRING NOT NULL OPTIONS(description="The row's identity within its origin: a node reference for `corpus`, the feed's `id:` expression otherwise."),
  `_origin` STRING NOT NULL OPTIONS(description="The feed that wrote the row: `corpus`, or a feed's name."),
  `_loaded_at` TIMESTAMP NOT NULL OPTIONS(description="When the feed SQL wrote the row."),
  `_source` STRING OPTIONS(description="The catalog slug the row's facts came from, when known."),
  `_corpus_commit` STRING OPTIONS(description="The commit a `corpus` row was exported from; null for every other origin."),
  `cidr` STRING,
  PRIMARY KEY (`id`, `_origin`) NOT ENFORCED
) OPTIONS(description="Network");

CREATE TABLE IF NOT EXISTS `edge_compute_instance__attached_to` (
  `src_id` STRING NOT NULL OPTIONS(description="The `id` of the authoring row."),
  `dst_id` STRING NOT NULL OPTIONS(description="The `id` of the row linked to."),
  `_origin` STRING NOT NULL OPTIONS(description="The feed that wrote the row: `corpus`, or a feed's name."),
  `_loaded_at` TIMESTAMP NOT NULL OPTIONS(description="When the feed SQL wrote the row."),
  `_source` STRING OPTIONS(description="The catalog slug the row's facts came from, when known."),
  PRIMARY KEY (`src_id`, `dst_id`, `_origin`) NOT ENFORCED
);

CREATE TABLE IF NOT EXISTS `vocab_compute_instance__provider` (
  `value` STRING NOT NULL,
  PRIMARY KEY (`value`) NOT ENFORCED
) OPTIONS(description="The values `compute-instance.provider` declares. A feed whose rows hold any other value fails.");

INSERT INTO `vocab_compute_instance__provider` (`value`)
SELECT v FROM UNNEST(["gcp", "aws"]) AS v
WHERE v NOT IN (SELECT `value` FROM `vocab_compute_instance__provider`);
